GA = 'A. Unlock-gated content (credits, CoroCoro, Album B, unlockable stamps and games)'
GB = 'B. TCRF "Unused" sections (music, graphics, hot-spot effects, code)'
GC = 'C. TCRF "Regional Differences": what the Japanese side shows'
