add('C20', GC, 'Super Game Boy border (Pocket Camera logo)', 'Logo changed accordingly', [R(0x0B, 0x4000, 0x7FFF)], 'data', 'screenshot', 'SGB data bank 0B, sent by the packet code 00:1D38-1EA0 (PAL_SET 4020, PAL_TRN 40A6, CHR_TRN 4156 and 5166, PCT_TRN 6176; each carries 4 KB that overlaps its neighbours). The border rebuilt from these bytes (4bpp tiles, 32 x 32 map, palettes 4-5) is pixel-identical (34,304 of 34,304 border pixels) to BGB running the ROM as a Super Game Boy and to the community sheet Super Game Boy Borders (lower picture: Pocket Camera logo). The international ROM has the same packets at the same bank-0B addresses and the Game Boy Camera logo (identical to BGB and to the sheet\'s upper picture). The game window is drawn with PAL_TRN palette 16 (BGB: its 4 colours). The tail my core never read is part of these transfers, which only run when the Super Game Boy is detected. Layout: assets/asset_map_jp.csv, tool tcrf_check/tools/sgb_border_check.py (C, README 16.13).', 'C', 'assets/never_read/sgb_border_jp_rom_vs_bgb.png')
rows = []
for (iid, g, item, tc, rng, kind, meth, ver, tag, asset) in I:
    st, n, pt, po, pr = cov(rng, kind) if rng else ('n/a', 0, 0, 0, 0)
    asset = ' '.join(os.path.normpath(t) for t in asset.split())
    rows.append(dict(id=iid, group=g, item=item, tcrf=tc, rom=ROMTXT.get(iid) or (loc(rng) if rng else '-'), bytes=n, coverage=st, touched_pct='%.0f' % pt if n else '', organic_pct='%.0f' % po if n else '', exec_or_read_pct='%.0f' % pr if n else '', kind=kind, method=meth, verdict=ver, tag=tag, asset=asset))
CELL_OVR = {'B11': {'coverage': 'forced-only (B CANCEL)', 'organic_pct': '0'}}   # hand-set cells the range arithmetic cannot give
for r in rows: r.update(CELL_OVR.get(r['id'], {}))
with open(sys.argv[3], 'w', newline='', encoding='utf-8') as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0].keys()), lineterminator='\n'); w.writeheader(); [w.writerow(r) for r in rows]
with open(sys.argv[2], 'w', encoding='utf-8', newline='\n') as f:
    f.write('# TCRF documented content, checked against the Japanese Pocket Camera ROM (md5 fdcfe686cf4df461e870b6e53b2b5a8b)\n\n')
    f.write('AI slop, do not trust until human validation.\n\n')
    f.write('* **TCRF says** paraphrases the OCR of the TCRF PDFs you supplied (`tcrf/t1-*.txt`, `t2-*.txt`).\n')
    f.write('* **Coverage** comes from the merged run v8 (`coverage/v8/merged_v8/cov.npz`): *touched* = executed (code) or read (data) in any run, *organic* = in runs driven by the joypad and an SRAM image only. "forced-only" / "never touched" describe MY runs, not the console.\n')
    f.write('* **Tags**: C = code/data traced or seen on a screenshot of the ROM; I = inferred (visual or structural match); ? = inconclusive or not located (never guessed).\n')
    f.write('* Asset paths are relative to `tcrf_check/` (`work/atlas_modes/` = contact sheets of the per-mode screens).\n')
    cur = None
    for r in rows:
        if r['group'] != cur:
            cur = r['group']; f.write('\n## %s\n\n| id | item (TCRF says) | ROM location | coverage touched / organic | finding | tag | assets |\n|---|---|---|---|---|---|---|\n' % cur)
        cv = ('%s (%s%% / %s%%, %d B)' % (r['coverage'], r['touched_pct'], r['organic_pct'], r['bytes'])) if r['bytes'] else r['coverage']
        if r['bytes'] and r['kind'] == 'code': cv += '<br>executed share; executed-or-read: %s%%' % r['exec_or_read_pct']
        f.write('| %s | **%s**<br>_%s_ | %s | %s | %s | %s | %s |\n' % (r['id'], r['item'].replace('|', '/'), r['tcrf'].replace('|', '/'), r['rom'], cv, r['verdict'].replace('|', '/'), r['tag'], r['asset'].replace('|', '/')))
    c = Counter()
    for r in rows:
        tg = r['tag']
        c['located / traced (C)' if tg.startswith('C') and '?' not in tg else ('inferred (I)' if tg.startswith('I') and '?' not in tg else 'with an open point (?)')] += 1
    f.write('\n## Summary\n\n' + ' · '.join('%s: %d' % kv for kv in sorted(c.items())) + ' (of %d items)\n' % len(rows))
print(len(rows), 'items', dict(c))
